📊 设备状态分布饼图：

```flint
{
  "data": {
    "values": [
      { "status": "正常运行", "count": 35 },
      { "status": "警告", "count": 1 },
      { "status": "故障", "count": 1 }
    ]
  },
  "semantic_types": { "status": "Category", "count": "Quantity" },
  "chart_spec": {
    "chartType": "Pie Chart",
    "encodings": { "color": { "field": "status" }, "theta": { "field": "count" } },
    "chartProperties": { "donutHole": 0.4 }
  }
}
```

